package com.ruoyi.metal.service;

import com.alibaba.fastjson2.JSON;
import com.alibaba.fastjson2.JSONWriter;
import com.ruoyi.common.exception.ServiceException;
import java.math.BigDecimal;
import java.math.RoundingMode;
import java.util.*;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import static com.ruoyi.metal.service.StorageSupport.*;

/** Controlled book opening: old production facts are referenced, never replayed as new business. */
@Service
public class ProductionBatchLegacyAdoptionService {
 private final JdbcTemplate jdbc;
 public ProductionBatchLegacyAdoptionService(JdbcTemplate jdbc){this.jdbc=jdbc;}
 private List<Map<String,Object>> rows(String sql,Object...args){return jdbc.queryForList(ProductionBatchMaterialService.currentRead(sql),args);}
 private Map<String,Object> one(String sql,Object...args){var r=rows(sql,args);if(r.size()!=1)throw fail("历史承接对象不存在或范围不唯一");return r.get(0);}
 private static long n(Object v){return v==null?0:v instanceof Boolean b?(b?1:0):Long.parseLong(v.toString());}
 private static BigDecimal w(Object v){return v==null?BigDecimal.ZERO.setScale(2):new BigDecimal(v.toString()).setScale(2,RoundingMode.UNNECESSARY);}
 private static void require(boolean valid,String message){if(!valid)throw new ServiceException(message,409);}
 private void admin(long actor){require(actor==1&&jdbc.queryForObject("SELECT COUNT(*) FROM sys_user WHERE user_id=? AND status='0' AND del_flag='0'",Integer.class,actor)==1,"历史承接仅限受控管理员");}
 private static List<Long> ids(Object value){if(!(value instanceof List<?> list))throw fail("请提供明确的历史对象编号清单");return list.stream().map(StorageSupport::id).toList();}

 /** Largest-remainder book allocation; this does not claim physical per-piece provenance. */
 static List<BigDecimal> bookParts(BigDecimal total,List<BigDecimal> capacities){
  BigDecimal sum=capacities.stream().reduce(BigDecimal.ZERO,BigDecimal::add);require(total.signum()>=0&&total.compareTo(sum)<=0&&capacities.stream().allMatch(x->x.signum()>=0),"历史账面贡献超过已证实来源");
  if(sum.signum()==0){require(total.signum()==0,"历史来源为空");return capacities.stream().map(x->BigDecimal.ZERO.setScale(2)).toList();}
  var result=new ArrayList<BigDecimal>();var fractions=new ArrayList<BigDecimal>();BigDecimal allocated=BigDecimal.ZERO;
  for(var cap:capacities){var exact=total.multiply(cap).divide(sum,20,RoundingMode.DOWN);var part=exact.setScale(2,RoundingMode.DOWN);result.add(part);fractions.add(exact.subtract(part));allocated=allocated.add(part);}
  int cents=total.subtract(allocated).movePointRight(2).intValueExact();var order=new ArrayList<Integer>();for(int i=0;i<capacities.size();i++)order.add(i);order.sort(Comparator.<Integer,BigDecimal>comparing(fractions::get).reversed().thenComparingInt(i->i));
  for(int i=0;i<cents;i++){int k=order.get(i);result.set(k,result.get(k).add(new BigDecimal("0.01")));}return result;
 }
 private List<Map<String,Object>> roots(long factory,long execution,long customer,String processing){
  require(rows("SELECT id FROM metal_production_execution_event WHERE factory_id=? AND execution_id=? AND event_type='INPUT' AND reversed=0 AND source_execution_id IS NOT NULL",factory,execution).isEmpty(),"跨工序旧来源须另行核实，不接受自动期初推断");
  var result=rows("SELECT a.id rootIssueAllocationId,a.source_owner_id sourceOwnerId,a.customer_id currentOwnerId,a.received_weight-a.returned_weight capacity,a.line_id issueLineId,ev.id productionEventId FROM metal_production_execution_event ev JOIN metal_storage_issue_allocation a ON a.factory_id=ev.factory_id AND a.document_id=ev.document_id AND a.line_id=ev.line_id WHERE ev.factory_id=? AND ev.execution_id=? AND ev.event_type='INPUT' AND ev.reversed=0 ORDER BY a.id",factory,execution);
  for(var r:result){require(n(r.get("currentOwnerId"))==customer&&w(r.get("capacity")).signum()>=0,"原领料客户或净来源无效");r.put("sourceKind",!"DIRECT_CUSTOM".equals(processing)&&n(r.get("sourceOwnerId"))==customer?"CUSTOMER":"FACTORY");}
  var net=new ProductionSourceBalances(jdbc).net(execution);for(int k=0;k<2;k++){String kind=k==0?"CUSTOMER":"FACTORY";var total=result.stream().filter(r->kind.equals(r.get("sourceKind"))).map(r->w(r.get("capacity"))).reduce(BigDecimal.ZERO,BigDecimal::add);require(total.compareTo(net.get(k))==0,"原领料根证据与历史净来源不一致");}return result;
 }
 private static List<Map<String,Object>> contributions(List<Map<String,Object>> roots,List<BigDecimal> composition){
  var result=new ArrayList<Map<String,Object>>();for(int k=0;k<2;k++){String kind=k==0?"CUSTOMER":"FACTORY";var selected=roots.stream().filter(r->kind.equals(r.get("sourceKind"))).toList();var parts=bookParts(composition.get(k),selected.stream().map(r->w(r.get("capacity"))).toList());for(int i=0;i<parts.size();i++)if(parts.get(i).signum()>0){var r=new LinkedHashMap<>(selected.get(i));r.put("weight",parts.get(i).toPlainString());r.put("quantity",null);r.put("allocationBasis","LEGACY_BOOK_CONTRIBUTION");result.add(r);}}return result;
 }
 @Transactional(readOnly=true)
 public Map<String,Object> preview(long actor,Map<String,Object> plan){
  admin(actor);long f=id(plan.get("factoryId")),oid=id(plan.get("orderId")),item=id(plan.get("orderItemId"));
  var order=one("SELECT * FROM metal_production_order WHERE factory_id=? AND id=? FOR UPDATE",f,oid);require(n(order.get("deleted"))==0&&Set.of("CREATED","IN_PROGRESS").contains(text(order.get("status")))&&n(order.get("flow_version"))>0,"订单不是可承接的冻结路线活动订单");long customer=id(order.get("customer_id"));
  var product=one("SELECT * FROM metal_production_order_item WHERE order_id=? AND id=? FOR UPDATE",oid,item);var route=rows("SELECT * FROM metal_production_order_step WHERE item_id=? ORDER BY sequence_no,id FOR UPDATE",item);require(!route.isEmpty()&&product.get("product_snapshot")!=null,"缺少冻结产品或路线");
  for(int k=0;k<route.size();k++){var r=route.get(k);require(n(r.get("sequence_no"))==k+1&&r.get("measurement_mode")!=null&&r.get("output_category")!=null&&r.get("process_snapshot")!=null,"历史冻结路线不完整");}
  require(rows("SELECT id FROM metal_production_batch WHERE factory_id=? AND order_item_id=? FOR UPDATE",f,item).isEmpty(),"产品组已有新批次，不能重复创建承接目标");
  var executions=rows("SELECT * FROM metal_production_execution WHERE factory_id=? AND order_item_id=? ORDER BY id FOR UPDATE",f,item);require(!executions.isEmpty(),"没有历史加工责任，请使用普通新建批次");
  var allIds=new TreeSet<Long>();for(var e:executions){require(e.get("batch_id")==null&&e.get("legacy_adoption_operation_id")==null&&Set.of("OPEN","CANCELLED").contains(text(e.get("status"))),"历史加工已映射、已承接或状态不允许");require(w(e.get("carry_in_weight")).signum()==0&&w(e.get("carry_out_weight")).signum()==0&&n(e.get("carry_in_quantity"))==0&&n(e.get("carry_out_quantity"))==0,"历史加工已有转移责任");require(rows("SELECT id FROM metal_production_material_source WHERE factory_id=? AND execution_id=? FOR UPDATE",f,e.get("id")).isEmpty(),"旧加工已有新来源，须先核实");allIds.add(n(e.get("id")));}
  var events=rows("SELECT ev.* FROM metal_production_execution_event ev JOIN metal_production_execution e ON e.id=ev.execution_id WHERE ev.factory_id=? AND e.order_item_id=? ORDER BY ev.id FOR UPDATE",f,item);
  var stocks=rows("SELECT DISTINCT st.* FROM metal_storage_stock st JOIN metal_production_execution_event ev ON ev.factory_id=st.factory_id AND ev.stock_id=st.id JOIN metal_production_execution e ON e.id=ev.execution_id WHERE st.factory_id=? AND e.order_item_id=? AND ev.event_type='OUTPUT' AND ev.reversed=0 AND (st.net_weight>0 OR st.quantity>0) ORDER BY st.id FOR UPDATE",f,item);
  var evidence=new LinkedHashMap<String,Object>();evidence.put("order",order);evidence.put("product",product);evidence.put("route",route);evidence.put("executions",executions);evidence.put("events",events);evidence.put("stocks",stocks);evidence.put("documents",rows("SELECT * FROM metal_storage_document WHERE factory_id=? AND order_id=? ORDER BY id FOR UPDATE",f,oid));
  evidence.put("documentLines",rows("SELECT l.* FROM metal_storage_document_line l JOIN metal_storage_document d ON d.factory_id=l.factory_id AND d.id=l.document_id WHERE d.factory_id=? AND d.order_id=? ORDER BY l.id FOR UPDATE",f,oid));
  evidence.put("issues",rows("SELECT * FROM metal_storage_issue_allocation WHERE factory_id=? AND work_order_id=? ORDER BY id FOR UPDATE",f,oid));
  var batches=new ArrayList<Object>();var usedIds=new TreeSet<Long>();var usedStocks=new TreeSet<Long>();long target=0;var keys=new HashSet<String>();var sourceBalances=new ProductionSourceBalances(jdbc);
  for(var batch:maps(plan.get("batches"))){String key=text(batch.get("key"));require(!key.isEmpty()&&keys.add(key),"结果批次标识为空或重复");long planned=quantity(batch.get("plannedQuantity")).longValueExact();require(planned>0,"承接目标须为正整数");target=Math.addExact(target,planned);long receiver=id(batch.get("processorId"));require(personCan(jdbc,receiver,f,"metal:warehouse-order:receive"),"NEEDS_RECEIVER_PERMISSION: 承接人须为本厂启用且有生产领料复验权限的人员");
   long step=id(batch.get("orderStepId"));var stage=route.stream().filter(r->n(r.get("id"))==step).findFirst().orElseThrow(()->fail("承接工序不属于冻结路线"));require(n(stage.get("sequence_no"))==1&&n(stage.get("execution_closed"))==0,"本次仅支持未关闭首道历史责任承接");
   var components=new ArrayList<Object>();for(long eid:ids(batch.get("executionIds"))){require(usedIds.add(eid),"历史加工重复分配");var e=executions.stream().filter(r->n(r.get("id"))==eid).findFirst().orElseThrow(()->fail("加工不属于本产品组"));var activeEvents=events.stream().filter(r->n(r.get("execution_id"))==eid&&!Boolean.TRUE.equals(r.get("reversed"))&&n(r.get("reversed"))==0).toList();var remaining=sourceBalances.remaining(eid);BigDecimal total=remaining.get(0).add(remaining.get(1));
    if(total.signum()==0){require(activeEvents.isEmpty()&&w(e.get("input_weight")).signum()==0&&w(e.get("output_weight")).signum()==0&&w(e.get("returned_weight")).signum()==0&&w(e.get("recovered_weight")).signum()==0&&w(e.get("loss_weight")).signum()==0&&n(e.get("input_quantity"))==0&&n(e.get("output_quantity"))==0,"零余额历史并非空占位，须另行核实");components.add(Map.of("executionId",eid,"kind","EMPTY","weight","0.00","quantity",0,"contributions",List.of()));}
    else{require("OPEN".equals(e.get("status"))&&n(e.get("order_step_id"))==step&&n(e.get("processor_id"))==receiver,"实际在制必须同工序并保留原接收人");require(n(e.get("input_quantity"))==0&&n(e.get("output_quantity"))==0,"本次历史账面承接不推断逐来源件数");var roots=roots(f,eid,customer,text(order.get("processing_type")));components.add(Map.of("executionId",eid,"kind","WIP","weight",total.toPlainString(),"quantity",0,"contributions",contributions(roots,remaining)));}
   }
   var stockComponents=new ArrayList<Object>();for(long sid:ids(batch.get("stockIds"))){require(usedStocks.add(sid),"历史库存重复分配");var st=stocks.stream().filter(r->n(r.get("id"))==sid).findFirst().orElseThrow(()->fail("库存不属于本产品组有效产出"));require(n(st.get("origin_step_id"))==step&&n(st.get("quantity"))==0,"本次仅承接当前工序的重量库存组件");var receipt=one("SELECT ev.* FROM metal_production_execution_event ev JOIN metal_storage_event se ON se.factory_id=ev.factory_id AND se.document_id=ev.document_id AND se.line_id=ev.line_id JOIN metal_storage_document d ON d.id=ev.document_id AND d.factory_id=ev.factory_id WHERE ev.factory_id=? AND ev.stock_id=? AND ev.event_type='OUTPUT' AND ev.reversed=0 AND se.action='INBOUND' AND se.reversed_by IS NULL AND d.status='POSTED' AND d.deleted=0 FOR UPDATE",f,sid);require(w(receipt.get("weight")).compareTo(w(st.get("net_weight")))==0,"历史库存已经部分使用，须另核来源分配");
    var sl=one("SELECT * FROM metal_storage_batch_slice WHERE factory_id=? AND stock_id=? FOR UPDATE",f,sid);require(sl.get("batch_id")==null&&sl.get("legacy_adoption_operation_id")==null&&"UNASSIGNED".equals(sl.get("slice_kind"))&&w(sl.get("weight")).compareTo(w(st.get("net_weight")))==0,"历史库存不是完整未分配份额");
    require(rows("SELECT r.id FROM metal_storage_reservation r JOIN metal_storage_reservation_session s ON s.factory_id=r.factory_id AND s.session_id=r.session_id WHERE r.factory_id=? AND r.stock_id=? AND (s.status='BOUND' OR (s.status='TEMP' AND s.expires_at>NOW())) FOR UPDATE",f,sid).isEmpty(),"历史库存仍有有效预占");
    var owners=rows("SELECT * FROM metal_storage_batch_slice_owner WHERE factory_id=? AND stock_slice_id=? ORDER BY owner_id FOR UPDATE",f,sl.get("id"));require(owners.size()==1&&n(owners.get(0).get("owner_id"))==customer&&w(owners.get(0).get("weight")).compareTo(w(st.get("net_weight")))==0,"库存当前料权不支持唯一账面承接");
    long eid=n(receipt.get("execution_id"));var roots=roots(f,eid,customer,text(order.get("processing_type")));var composition=sourceBalances.output(eid,n(receipt.get("id")));var c=new LinkedHashMap<String,Object>();c.put("stockId",sid);c.put("stockSliceId",sl.get("id"));c.put("sourceExecutionId",eid);c.put("productionEventId",receipt.get("id"));c.put("weight",w(st.get("net_weight")).toPlainString());c.put("quantity",0);c.put("contributions",contributions(roots,composition));stockComponents.add(c);evidence.put("slice-"+sid,sl);evidence.put("sliceOwners-"+sid,owners);
   }
   var versioned=new ArrayList<Object>();for(Object raw:components){@SuppressWarnings("unchecked") var c=new LinkedHashMap<>((Map<String,Object>)raw);var original=executions.stream().filter(e->n(e.get("id"))==n(c.get("executionId"))).findFirst().orElseThrow();c.put("sourceVersion",original.get("version"));c.put("originalExecution",original);var net=sourceBalances.net(n(original.get("id")));c.put("netCustomerWeight",net.get(0).toPlainString());c.put("netFactoryWeight",net.get(1).toPlainString());versioned.add(c);}
   batches.add(Map.of("key",key,"plannedQuantity",planned,"processorId",receiver,"orderStepId",step,"executionComponents",versioned,"stockComponents",stockComponents));
  }
  require(target==n(product.get("quantity"))&&usedIds.equals(allIds),"须一次覆盖全部旧加工且目标总份额等于产品组目标");require(usedStocks.equals(new TreeSet<>(stocks.stream().map(r->n(r.get("id"))).toList())),"须明确覆盖全部现存生产库存");
  return new LinkedHashMap<>(Map.of("factoryId",f,"orderId",oid,"orderItemId",item,"plan",plan,"evidenceHash",hash(evidence),"batches",batches,"allocationBasis","LEGACY_BOOK_CONTRIBUTION","routeSnapshot",ProductionBatchService.routeSnapshot(jdbc,item)));
 }
 @Transactional(rollbackFor=Exception.class)
 public Map<String,Object> adopt(long actor,String requestId,String manifestHash,Map<String,Object> manifest){
  admin(actor);String request=uuid(requestId);long f=id(manifest.get("factoryId"));one("SELECT factory_id FROM metal_factory WHERE factory_id=? AND del_flag='0' FOR UPDATE",f);require(hash(manifest).equals(manifestHash),"承接清单指纹不一致");
  var prior=rows("SELECT action,request_hash,CAST(result AS CHAR) result FROM metal_production_execution_operation WHERE factory_id=? AND actor_id=? AND request_id=? FOR UPDATE",f,actor,request);if(!prior.isEmpty()){var p=prior.get(0);require("LEGACY_ADOPT".equals(p.get("action"))&&manifestHash.equals(p.get("request_hash")),"相同请求标识的承接内容已变化");return JSON.parseObject(p.get("result").toString());}
  @SuppressWarnings("unchecked") var plan=(Map<String,Object>)manifest.get("plan");require(hash(preview(actor,plan)).equals(manifestHash),"历史承接清单已过期，请重新预览");
  long oid=id(manifest.get("orderId")),item=id(manifest.get("orderItemId"));long op=insert(jdbc,"INSERT INTO metal_production_execution_operation(factory_id,actor_id,request_id,action,request_hash,result) VALUES(?,?,?,'LEGACY_ADOPT',?,'{}')",f,actor,request,manifestHash);
  var mappings=new ArrayList<Object>();var stockMappings=new ArrayList<Object>();var results=new ArrayList<Object>();var batchService=new ProductionBatchService(jdbc,null,null);
  for(var b:maps(manifest.get("batches"))){long bid=insert(jdbc,"INSERT INTO metal_production_batch(factory_id,number,order_id,order_item_id,route_snapshot,planned_quantity,origin_action,origin_operation_id,completed_step_ids,create_by) VALUES(?,?,?,?,?,?,'MIGRATION',?,'[]',?)",f,batchService.nextNumber(),oid,item,JSON.toJSONString(manifest.get("routeSnapshot")),b.get("plannedQuantity"),op,actor);afterBatchCreated();
   var components=maps(b.get("executionComponents"));boolean hasWip=components.stream().anyMatch(c->"WIP".equals(c.get("kind")));Long target=hasWip?insert(jdbc,"INSERT INTO metal_production_execution(factory_id,order_id,order_item_id,order_step_id,processor_id,planned_quantity,inherited_snapshot,create_by,batch_id) VALUES(?,?,?,?,?,?,'[]',?,?)",f,oid,item,b.get("orderStepId"),b.get("processorId"),b.get("plannedQuantity"),actor,bid):null;
   for(var c:components){long source=id(c.get("executionId"));var m=new LinkedHashMap<String,Object>();m.put("sourceExecutionId",source);m.put("targetExecutionId","WIP".equals(c.get("kind"))?target:null);m.put("batchId",bid);m.put("kind",c.get("kind"));m.put("weight",c.get("weight"));m.put("quantity",c.get("quantity"));m.put("sourceContributions",c.get("contributions"));m.put("netCustomerWeight",c.get("netCustomerWeight"));m.put("netFactoryWeight",c.get("netFactoryWeight"));m.put("sourceVersion",c.get("sourceVersion"));mappings.add(m);
    if("WIP".equals(c.get("kind"))){long transfer=insert(jdbc,"INSERT INTO metal_production_wip_transfer(factory_id,operation_id,source_execution_id,target_execution_id,order_step_id,weight,quantity,allocation_basis) VALUES(?,?,?,?,?,?,0,'LEGACY_BOOK_CONTRIBUTION')",f,op,source,target,b.get("orderStepId"),c.get("weight"));for(var p:maps(c.get("contributions")))opening(f,op,null,target,transfer,"WIP_TRANSFER",p);jdbc.update("UPDATE metal_production_execution SET carry_out_weight=carry_out_weight+? WHERE factory_id=? AND id=?",c.get("weight"),f,source);jdbc.update("UPDATE metal_production_execution SET carry_in_weight=carry_in_weight+? WHERE factory_id=? AND id=?",c.get("weight"),f,target);m.put("transferId",transfer);}
    require(jdbc.update("UPDATE metal_production_execution SET legacy_adoption_operation_id=?,version=version+1 WHERE factory_id=? AND id=? AND legacy_adoption_operation_id IS NULL AND batch_id IS NULL",op,f,source)==1,"历史加工并发变化");
   }
   for(var c:maps(b.get("stockComponents"))){long slice=id(c.get("stockSliceId"));require(jdbc.update("UPDATE metal_storage_batch_slice SET batch_id=?,slice_kind='BATCH',legacy_adoption_operation_id=?,version=version+1 WHERE factory_id=? AND id=? AND batch_id IS NULL AND legacy_adoption_operation_id IS NULL",bid,op,f,slice)==1,"库存份额并发变化");for(var p:maps(c.get("contributions")))opening(f,op,slice,null,null,"IDENTITY_TRANSFER",p);var m=new LinkedHashMap<>(c);m.put("batchId",bid);stockMappings.add(m);new StorageBatchSliceService(jdbc,null).reconcile(f,id(c.get("stockId")));}
   var r=new LinkedHashMap<String,Object>();r.put("key",b.get("key"));r.put("batchId",bid);r.put("targetExecutionId",target);r.put("plannedQuantity",b.get("plannedQuantity"));results.add(r);
  }
  var result=new LinkedHashMap<String,Object>();result.put("factoryId",f);result.put("orderId",oid);result.put("orderItemId",item);result.put("operationId",op);result.put("requestId",request);result.put("manifestHash",manifestHash);result.put("evidenceHash",manifest.get("evidenceHash"));result.put("manifest",manifest);result.put("legacyExecutionMappings",mappings);result.put("stockComponents",stockMappings);result.put("batches",results);result.put("allocationBasis","LEGACY_BOOK_CONTRIBUTION");result.put("openingKind","LEGACY_OPENING");result.put("committed",true);jdbc.update("UPDATE metal_production_execution_operation SET result=? WHERE factory_id=? AND id=?",JSON.toJSONString(result,JSONWriter.Feature.WriteMapNullValue),f,op);return JSON.parseObject(jdbc.queryForObject("SELECT CAST(result AS CHAR) FROM metal_production_execution_operation WHERE factory_id=? AND id=?",String.class,f,op));
 }
 private void opening(long f,long op,Long slice,Long target,Long transfer,String purpose,Map<String,Object> p){
  long source=insert(jdbc,"INSERT INTO metal_production_material_source(factory_id,stock_slice_id,execution_id,root_issue_allocation_id,current_owner_id,source_owner_id,source_kind,initial_weight,initial_quantity,weight,quantity,returnable_weight,returnable_quantity,legacy_adoption_operation_id) VALUES(?,?,?,?,?,?,?,?,NULL,?,NULL,0,0,?)",f,slice,target,p.get("rootIssueAllocationId"),p.get("currentOwnerId"),p.get("sourceOwnerId"),p.get("sourceKind"),p.get("weight"),p.get("weight"),op);
  jdbc.update("INSERT INTO metal_production_material_allocation(factory_id,operation_id,from_source_id,to_source_id,wip_transfer_id,purpose,weight,quantity,allocation_basis) VALUES(?,?,NULL,?,?,?,?,NULL,'LEGACY_BOOK_CONTRIBUTION')",f,op,source,transfer,purpose,p.get("weight"));
 }
 void afterBatchCreated(){}
}
